window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a51be1903573984"]={"versions": [{"id": "FIG-3a51be1903573984", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Main Function Activation Supervision</code>) im Kontext des AUTOSAR Watchdog Managers (WdgM). Das Diagramm spezifiziert die periodische Aktivierung der Alive-Überwachung durch den Scheduler (Betriebssystem bzw. BSW-Scheduler) und die daraus resultierende interne Prüfung der Zählerstände innerhalb des WdgM.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Scheduler (OS task or cyclic call)</code>: Aufrufende Instanz (z. B. Task des AUTOSAR OS oder zyklischer Aufruf über den BSW-Scheduler).\n</li><li><code>:WdgM</code>: Instanz des Basissoftware-Moduls Watchdog Manager.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf <code>WdgM_MainFunction_AliveSupervision()</code> vom Scheduler an <code>:WdgM</code>.\n</li><li>Interner Selbstaufruf / interne Aktion <code>Check Alive Counters</code> auf der <code>:WdgM</code>-Instanz.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Scheduler (OS task or cyclic call)</code> initiiert synchron die periodische Ausführung über den Funktionsaufruf <code>WdgM_MainFunction_AliveSupervision()</code> an <code>:WdgM</code>.\n</li><li>Während der aktiven Ausführung führt <code>:WdgM</code> intern den synchronen Selbstaufruf <code>Check Alive Counters</code> aus, um die Alive-Zähler der überwachten Entitäten zu evaluieren.\n</li><li>Nach Abschluss der internen Überprüfung kehrt der Kontrollfluss via gestrichelter Antwortnachricht (Return) zum aufrufenden Scheduler zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktion <code>WdgM_MainFunction_AliveSupervision</code> ist als periodische Hauptfunktion der Basissoftware für die Alive-Überwachung zu konfigurieren (Scheduling im OS oder BSW-Scheduler). Integratoren müssen ein Zyklusintervall konfigurieren, das zu den parametrierten Alive-Überwachungszeiträumen der Supervised Entities passt. Die interne Zählerprüfung findet im Kontext dieser Main-Function-Aktivierung statt.</p>"}, {"id": "FIG-838b2397424fca20", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd WdgM_Main Function Activation Supervision</code>) im Kontext des AUTOSAR Watchdog Managers (WdgM). Das Diagramm spezifiziert die periodische Aktivierung der Alive-Überwachung durch den Scheduler (Betriebssystem bzw. BSW-Scheduler) und die daraus resultierende interne Prüfung der Zählerstände innerhalb des WdgM.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Scheduler (OS task or cyclic call)</code>: Aufrufende Instanz (z. B. Task des AUTOSAR OS oder zyklischer Aufruf über den BSW-Scheduler).\n</li><li><code>:WdgM</code>: Instanz des Basissoftware-Moduls Watchdog Manager.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf <code>WdgM_MainFunction_AliveSupervision()</code> vom Scheduler an <code>:WdgM</code>.\n</li><li>Interner Selbstaufruf <code>Check Alive Counters()</code> auf der <code>:WdgM</code>-Instanz.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Scheduler (OS task or cyclic call)</code> initiiert synchron die periodische Ausführung über den Funktionsaufruf <code>WdgM_MainFunction_AliveSupervision()</code> an <code>:WdgM</code>.\n</li><li>Während der aktiven Ausführung führt <code>:WdgM</code> intern den synchronen Selbstaufruf <code>Check Alive Counters()</code> aus, um die Alive-Zähler der überwachten Entitäten zu evaluieren.\n</li><li>Nach Abschluss der internen Überprüfung kehrt der Kontrollfluss via gestrichelter Antwortnachricht (Return) zum aufrufenden Scheduler zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Funktion <code>WdgM_MainFunction_AliveSupervision</code> ist als periodische Hauptfunktion der Basissoftware für die Alive-Überwachung zu konfigurieren (Scheduling im OS oder BSW-Scheduler). Integratoren müssen ein Zyklusintervall konfigurieren, das zu den parametrierten Alive-Überwachungszeiträumen der Supervised Entities passt. Die interne Zählerprüfung findet im Kontext dieser Main-Function-Aktivierung statt.</p>"}], "trans": [{"from": "FIG-3a51be1903573984", "to": "FIG-838b2397424fca20", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammtitel (sd-Kopfzeile): Erweitert von <code>Main Function Activation Supervision</code> zu <code>WdgM_Main Function Activation Supervision</code>.\n</li><li>Interne Operation an <code>:WdgM</code>: Ergänzung von Klammern beim Selbstaufruf (<code>Check Alive Counters</code> geändert zu <code>Check Alive Counters()</code>).\n</li></ul>"}]};
